<?php require __DIR__.'/../config/bootstrap.php'; require_admin(); /* This check was missing: the POST handler below ran before includes/admin_header.php performed the login check, so anyone holding a CSRF token from the public contact form could add or delete records while signed out. */ $admin_title='Services'; if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$a=$_POST['action']??'';if($a==='save'){$id=(int)($_POST['id']??0);$title=post_text('title');$short=post_text('short_text');$desc=post_text('description');$icon=post_text('icon','fa-solid fa-ruler-combined');$sort=post_int('sort_order');$active=isset($_POST['active'])?1:0;if($title===''||$short===''||$desc==='')throw new UserMessageException('Please fill in the title, short text and description before saving.');if($id)db()->prepare('UPDATE services SET title=?,short_text=?,description=?,icon=?,sort_order=?,active=? WHERE id=?')->execute([$title,$short,$desc,$icon,$sort,$active,$id]);else db()->prepare('INSERT INTO services(title,short_text,description,icon,sort_order,active) VALUES(?,?,?,?,?,?)')->execute([$title,$short,$desc,$icon,$sort,$active]);flash('success','Service saved.');}elseif($a==='delete'){db()->prepare('DELETE FROM services WHERE id=?')->execute([post_int('id')]);flash('success','Service deleted.');}header('Location: '.url('admin/services.php'));exit;}catch(Throwable $e){flash_exception($e);header('Location: '.url('admin/services.php'));exit;}}$edit=null;if(isset($_GET['edit'])){$st=db()->prepare('SELECT * FROM services WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}$items=db()->query('SELECT * FROM services ORDER BY sort_order,id')->fetchAll();require __DIR__.'/../includes/admin_header.php'; ?><div class="admin-card"><div class="admin-card-head"><div><h2><?=$edit?'Edit service':'Add service'?></h2><p>Use Font Awesome icon classes such as fa-solid fa-ruler-combined.</p></div></div><form method="post" class="admin-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><div class="form-cols"><div><label>Title</label><input required name="title" value="<?=e($edit['title']??'')?>"></div><div><label>Short text</label><input required name="short_text" value="<?=e($edit['short_text']??'')?>"></div><div class="wide"><label>Description</label><textarea name="description" rows="5" required><?=e($edit['description']??'')?></textarea></div><div><label>Icon class</label><input name="icon" value="<?=e($edit['icon']??'fa-solid fa-ruler-combined')?>"></div><div><label>Sort order</label><input type="number" name="sort_order" value="<?=e($edit['sort_order']??0)?>"></div></div><label class="check"><input type="checkbox" name="active" <?=($edit===null||!empty($edit['active']))?'checked':''?>> Show publicly</label><button class="admin-button">Save Service</button></form></div><div class="admin-card"><table class="table"><thead><tr><th>Icon</th><th>Service</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($items as $x):?><tr><td><i class="<?=e($x['icon'])?>"></i></td><td><strong><?=e($x['title'])?></strong><small><?=e($x['short_text'])?></small></td><td><?=!empty($x['active'])?'Visible':'Hidden'?></td><td class="actions"><a href="?edit=<?=(int)$x['id']?>">Edit</a><form method="post" data-confirm="Delete this service?"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$x['id']?>"><button>Delete</button></form></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../includes/admin_footer.php'; ?>